Q: async exec in python A: <p>Here's another solution that avoids the pesky wrap-in-a-function method.</p>
<p>As &quot;exec&quot; compiles top-level code and thus can't handle <code>return</code> we'll replace that with an exception.</p>
<pre><code>
import ast

lass ReturnValue(BaseException):
    &quot;&quot;&quot;
    Internal signal used to return values from compiled snippets.
    &quot;&quot;&quot;

    value: Any

    def __init__(self, value: Any) -&gt; None:
        super().__init__(value)
        self.value = value


class _ReturnRewriter(ast.NodeTransformer):
    &quot;&quot;&quot;
    Rewrite module-level ``return`` statements to ``raise ReturnValue``.
    &quot;&quot;&quot;

    _scope_level: int

    def __init__(self) -&gt; None:
        super().__init__()
        self._scope_level = 0

    def _enter_scope(self, node: ast.AST) -&gt; ast.AST:
        self._scope_level += 1
        try:
            return self.generic_visit(node)
        finally:
            self._scope_level -= 1

    def visit_FunctionDef(self, node: ast.FunctionDef) -&gt; ast.AST:
        return self._enter_scope(node)

    def visit_AsyncFunctionDef(self, node: ast.AsyncFunctionDef) -&gt; ast.AST:
        return self._enter_scope(node)

    def visit_ClassDef(self, node: ast.ClassDef) -&gt; ast.AST:
        return self._enter_scope(node)

    def visit_Lambda(self, node: ast.Lambda) -&gt; ast.AST:
        return self._enter_scope(node)

    def visit_Return(self, node: ast.Return) -&gt; ast.AST:
        if self._scope_level:
            return self.generic_visit(node)
        value = node.value
        if value is None:
            value = ast.Constant(value=None)
        else:
            value = self.visit(value)
        ret = ast.Raise(
            exc=ast.Call(
                func=ast.Name(id=&quot;ReturnValue&quot;, ctx=ast.Load()),
                args=[value],
                keywords=[],
            ),
            cause=None,
        )
        return ast.copy_location(ret, node)

def make_proc(code: str, path: Any, *, use_async: bool = False) -&gt; CodeType:
    &quot;&quot;&quot;
    Compile snippet code directly for eval/await execution.
    &quot;&quot;&quot;
    flags = ast.PyCF_ALLOW_TOP_LEVEL_AWAIT if use_async else 0
    tree = compile(code, str(path), &quot;exec&quot;, flags=flags | ast.PyCF_ONLY_AST)
    tree = _ReturnRewriter().visit(tree)
    ast.fix_missing_locations(tree)
    return compile(tree, str(path), &quot;exec&quot;, flags=flags)

...
try:
    proc = make_proc(&quot;return 42;\n&quot;, &quot;&lt;Example&gt;&quot;)
    res = eval(proc, globals=..., locals=...)
    if use_async:
        await res
except ReturnValue as exc:
    return exc.value
else:
    return None
</code></pre>

Q: How do I check that a given cell is within a range? A: <p>There seems to be no API method to check this. You could try something like this:</p>
<pre class="lang-js prettyprint-override"><code>// find if checkRange is within inRange
function isSubset(checkRange, inRange) {
  return (
    (checkRange.getRow() &gt;= inRange.getRow()) &amp;&amp; 
    (checkRange.getColumn() &gt;= inRange.getColumn()) &amp;&amp; 
    (checkRange.getRow() + checkRange.getNumRows() &lt;= inRange.getRow() + inRange.getNumRows()) &amp;&amp; 
    (checkRange.getColumn() + checkRange.getNumColumns() &lt;= inRange.getColumn() + inRange.getNumColumns())
  ); 
}
</code></pre>

Q: Where can I view all my custom keybindings in bash? A: <p>To check all custom keybindings currently set, run <code>bind -X</code></p>
<p>It will show something like:</p>
<pre><code>&quot;\C-i&quot;: &quot;fzf_bash_completion&quot;
&quot;\C-r&quot;: &quot;__fzf_history__&quot;
&quot;\C-t&quot;: &quot;fzf-file-widget&quot;
&quot;\es&quot;: &quot;my_completion&quot;
</code></pre>

Q: Flutter StreamBuilder to monitor for Firebase Auth state A: <p>The issue happens because the <code>VideoPlayerController</code> is not fully initialized before being used.</p>
<p>Make sure you initialize the controller inside <code>initState()</code> and call <code>setState()</code> after initialization so the widget rebuilds.</p>
<p>Here is the correct example:</p>
<pre><code>@override
void initState() {
  super.initState();
  _controller = VideoPlayerController.network(widget.videoUrl)
    ..initialize().then((_) {
      setState(() {});
      _controller.play();
      _controller.setLooping(true);
    });
}
</code></pre>
<p>Also, make sure you dispose the controller properly:</p>
<pre><code>@override
void dispose() {
  _controller.dispose();
  super.dispose();
}
</code></pre>
